import React, { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { Menubar } from "primereact/menubar";
import { Avatar } from "primereact/avatar";
import { Menu } from "primereact/menu";
import { InputText } from "primereact/inputtext";
import { Button } from "primereact/button";

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [avatar, setAvatar] = useState("/assets/default-avatar.png");
  const menuRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      try {
        const owner = JSON.parse(ownerData);
        setAvatar(owner.avatar || "/assets/default-avatar.png");
      } catch (error) {
        console.error("Error parsing owner data:", error);
      }
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    setIsLoggedIn(false);
    setAvatar("/assets/default-avatar.png");
    navigate("/login");
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem("ownerId");
    if (ownerId) {
      navigate(`/profile/${ownerId}`);
    }
  };

  const menuItems = [
    { label: "Home", icon: "pi pi-home", command: () => navigate("/") },
    !isLoggedIn
      ? { label: "Log In", icon: "pi pi-sign-in", command: () => navigate("/login") }
      : null,
  ].filter(Boolean);

  const userMenuItems = [
    { label: "Profile", icon: "pi pi-user", command: handleProfileClick },
    { label: "Logout", icon: "pi pi-sign-out", command: handleLogout },
  ];

  return (
    <div className="shadow-md w-full">
      <Menubar
        model={menuItems}
        start={
          <img
            src={require("../assets/Logo.png")}
            alt="Petopia Logo"
            className="h-12 cursor-pointer"
            onClick={() => navigate("/")}
          />
        }
        end={
          isLoggedIn && (
            <div className="relative flex items-center gap-2">
              <Avatar
                image={avatar}
                className="cursor-pointer border border-gray-300"
                shape="circle"
                size="large"
                onClick={(e) => menuRef.current.toggle(e)}
              />
              <Menu model={userMenuItems} popup ref={menuRef} />
            </div>
          )
        }
        className="p-3 bg-white flex justify-between"
      />
      
      {/* 🔍 Search Bar and Filters */}
      <div className="flex items-center justify-center p-4 bg-gray-50">
        <div className="w-full max-w-4xl flex gap-3">
          <span className="p-input-icon-left w-full">
            <i className="pi pi-search" />
            <InputText placeholder="Search Pet Shops" className="w-full" />
          </span>
          <Button label="Location" icon="pi pi-map-marker" className="p-button-outlined" />
          <Button label="Services" icon="pi pi-filter" className="p-button-outlined" />
        </div>
      </div>
    </div>
  );
};
